"""make_rig13.py: regenerates rig13.py = build_head.py + the rig stage of ../hem_r11/rig11.py (mode A weights, slit, per-frame SkirtSw solve)."""
import os
d = os.path.dirname(os.path.abspath(__file__)); src = open(d + '/../hem_r11/rig11.py').read().split('\n')
i = [k for k, l in enumerate(src) if l.startswith('AMW = arm.matrix_world')][0]
cfg = '\n'.join(l for l in src if l.startswith(('NSW', 'MODE =', 'PSMAX', 'MARG,')))
body = '\n'.join(src[i:]).replace("SLIT = (-165, -45, 0.90) if MODE == 'A' else None", "SLIT = tuple(float(x) for x in O.get('slit', '-150,-60,0.90').split(',')) if MODE == 'A' else None")
body = body.replace("hh_ = PIV - p.z\n", "hh_ = PIV - p.z\n            if p.z < F('zlow', 0.0) or p.z > F('zhigh', 9.0): continue\n")
body = body.replace("G = sk.vertex_groups\n", "ps = ps * (1 - (1 - F('pslow', 1.0)) * ss(F('pl0', .45), F('pl1', .95), np.clip((ZT - P[:, 2]) / (ZT - ZH), 0, 1)))\nG = sk.vertex_groups\n", 1)
body = body.replace("export_skins=True,", "export_skins=True, export_all_influences=True,")
head = open(d + '/build_head.py').read()
open(d + '/rig13.py', 'w').write('"""rig13.py (generated by make_rig13.py): build_head.py + rig11 mode A weights/keys.\nblender -b -P rig13.py -- LIVE.glb OUT.glb [sk= sktex= ww= wd= kw= zhem= tris= | them= sh=0 slit=a,b,z keep=Idle,Attack marg=]"""\n' + head + '\n' + cfg + '\n' + body)
